-- 003: town -> MET district crosswalk (reference data).
-- Only rows that cannot be derived from name identity (a city whose name differs
-- from its district). The rest are computed at read time from the locality list and
-- the district registry, so there is no generated file and no separate data format.
-- NOTE: the town->district half is a person's assertion; the district->state half
-- comes from MET's own district selector.
CREATE TABLE IF NOT EXISTS town_districts (
  town_slug     TEXT PRIMARY KEY,
  district_name TEXT NOT NULL,
  source        TEXT NOT NULL,
  asserted_at   TEXT NOT NULL
);

